'use strict';
const ClassUI={
 selected:'assault',cards:[],soloCards:[],netCards:[],details:{},
 reset(){TZClasses.init(player,this.selected,time)},
 choose(id){if(!TZClasses.valid(id))return;this.selected=id;try{localStorage.setItem('tactical-class',id)}catch(_){}this.refresh()},
 mark(cards,selected,disabled=false){for(const {id,button}of cards){button.classList.toggle('selected',id===selected);button.setAttribute('aria-pressed',String(id===selected));button.disabled=disabled}},
 describe(container,id){const panel=$(container),role=TZClasses.ROLES[id];if(!role||panel.dataset.classId===id)return;let parts=this.details[container];if(!parts){parts={};for(const [key,tag]of [['name','span'],['skill','h3'],['description','p'],['timing','div'],['control','small']]){const el=document.createElement(tag);el.className='skillIntro-'+key;panel.appendChild(el);parts[key]=el}this.details[container]=parts}panel.dataset.classId=id;panel.style.setProperty('--class-color',role.color);parts.name.textContent=role.name+' · '+role.tag;parts.skill.textContent=role.skill;parts.description.textContent=role.detail;parts.timing.textContent='冷却 '+role.cooldown+' 秒 · '+(role.duration?'持续 '+role.duration+' 秒':'即时施放');parts.control.textContent='进入战场后按 F 或点击技能按钮施放';if(!window.matchMedia?.('(prefers-reduced-motion: reduce)').matches)panel.animate?.([{opacity:.35,transform:'translateY(8px)'},{opacity:1,transform:'translateY(0)'}],{duration:260,easing:'ease-out'})},
 refresh(){this.mark(this.cards,this.selected);this.mark(this.soloCards,this.selected);this.describe('classSkillIntro',this.selected);this.describe('soloSkillIntro',this.selected);OperatorArt.preview($('selectedClassModel'),this.selected)},
 pickNetwork(id){const s=TZNet.state;if(!s||!['lobby','finished'].includes(s.status))return;this.choose(id);TZNet.send({type:'class',classId:id})},
 cast(){if(!running||paused||editing||player?.hp<=0)return;if(gameMode==='multi'){TZNet.command('skill');return}const result=TZClasses.cast(player,{actors:()=>[player],allied:()=>false,world:worldGeometry,gun:()=>{player.type=player.weapon;return player},noise:(p,k,r)=>FieldOps.ops?.emit(p,k,r)},time);if(result.ok){Expedition.searching=null;sound('shield',.35)}toast(result.reason);this.hud()},
 hud(){if(!player)return;const role=TZClasses.ROLES[player.classId]||TZClasses.ROLES.assault,left=Math.max(0,Math.ceil((player.skillReadyAt||0)-time)),active=TZClasses.active(player,time);$('classSkill').textContent=role.skill+' [F]'+(active?' · '+Math.ceil(player.skillUntil-time)+'s':left?' · '+left+'s':'');$('classSkill').disabled=player.hp<=0||left>0||(gameMode==='multi'&&TZNet.state?.status!=='playing');$('classSkill').style.setProperty('--class-color',role.color);$('classSkill').title=role.name+'：'+role.detail;$('classStatus').textContent=role.name+(player.armorUntil>time&&player.armor>0?' · 护甲 '+Math.ceil(player.armor):'')},
 lobby(s){const me=s.roster.find(p=>p.id===TZNet.id),battle=['playing','countdown'].includes(s.status),id=me?.classId||this.selected;$('netClassPicker').hidden=battle;this.mark(this.netCards,id,battle);this.describe('netSkillIntro',id)},
 badge(g,a,dead){const role=TZClasses.ROLES[a.classId];if(!role)return;g.save();g.translate(a.x,a.y);g.globalAlpha=dead?.4:1;g.fillStyle='#152730';g.fillRect(-27,-13,16,16);g.strokeStyle=role.color;g.strokeRect(-27,-13,16,16);g.font='bold 12px system-ui';g.textAlign='center';g.fillStyle=role.color;g.fillText(role.mark,-19,0);if(!dead&&(TZClasses.active(a,time)||(a.armorUntil>time&&a.armor>0))){g.lineWidth=2;g.beginPath();g.arc(0,0,25,0,TAU);g.stroke()}const age=time-(a.skillCastAt??-100);if(!dead&&age>=0&&age<.6){g.globalAlpha=(1-age/.6)*.65;g.beginPath();g.arc(0,0,28+age*90,0,TAU);g.stroke()}g.restore()}
};
try{const saved=localStorage.getItem('tactical-class');if(TZClasses.valid(saved))ClassUI.selected=saved}catch(_){}
for(const [id,role]of Object.entries(TZClasses.ROLES))for(const [container,list,network]of [['classCards',ClassUI.cards,false],['soloClassCards',ClassUI.soloCards,false],['netClassCards',ClassUI.netCards,true]]){
 const button=document.createElement('button');button.type='button';button.className='portraitChoice';button.style.setProperty('--class-color',role.color);button.setAttribute('aria-pressed','false');button.setAttribute('aria-label',role.name+'：'+role.skill+'。'+role.detail);
 const portrait=document.createElement('img');portrait.className='classPortrait';portrait.src='assets/operators/'+id+'.png';portrait.alt=role.name+'全身立绘';portrait.loading='lazy';portrait.decoding='async';portrait.width=512;portrait.height=768;button.appendChild(portrait);button.addEventListener('click',()=>network?ClassUI.pickNetwork(id):ClassUI.choose(id));$(container).appendChild(button);list.push({id,button});
}
$('viewClasses').addEventListener('click',()=>{ClassUI.refresh();showScreen('classes')});$('classBack').addEventListener('click',()=>showScreen('home'));$('classSkill').addEventListener('click',()=>ClassUI.cast());
ClassUI.refresh();
